use openwebide_core::editor::{Document, Indentation, Selection, SelectionMotion};
use std::{hint::black_box, time::Instant};
use unicode_segmentation::UnicodeSegmentation;
fn old_right(text: &str) -> usize {
    let mut result = 0;
    let mut kind = None;
    for (offset, glyph) in text.grapheme_indices(true) {
        let current = if glyph.chars().all(char::is_whitespace) {0} else if glyph.chars().any(|c| c.is_alphanumeric() || c == '_') {1} else {2};
        if kind.is_some_and(|kind| kind != current) && current != 0 {break;}
        result = offset + glyph.len(); kind = Some(current);
    }
    result
}
fn main() {
    for (name, body) in [("ascii", "word_".repeat(180_000)), ("whitespace", format!("{}word", " ".repeat(900_000))), ("combining", format!("a{}", "\u{301}".repeat(300_000))), ("alternating", "w!".repeat(450_000))] {
        let source = format!("{body}  ++ tail");
        let started = Instant::now(); let mut doc = Document::new(&source); let preparation_ms = started.elapsed().as_secs_f64() * 1000.0;
        let expected = old_right(&source); let repetitions = 40;
        let started = Instant::now(); for _ in 0..repetitions { assert_eq!(black_box(old_right(black_box(&source))), expected); } let baseline_ms = started.elapsed().as_secs_f64() * 1000.0 / f64::from(repetitions);
        let mut elapsed = 0.0;
        for _ in 0..repetitions {doc.set_selections(vec![Selection::caret(0)]).unwrap(); let started = Instant::now(); doc.move_selections(SelectionMotion::WordRight, false, Indentation::default()).unwrap(); elapsed += started.elapsed().as_secs_f64() * 1000.0; assert_eq!(doc.selections(), [Selection::caret(expected)]);}
        println!("{{\"case\":\"{name}\",\"sourceBytes\":{},\"preparationMs\":{preparation_ms},\"baselineQueryMs\":{baseline_ms},\"indexedDocumentQueryMs\":{},\"repetitions\":{repetitions},\"exactTarget\":{expected}}}",source.len(),elapsed/f64::from(repetitions));
    }
}
